contract InvMutTest {
    C c;

    uint public firstCallFlag;
    uint public secondCallFlag;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _dummy) public {
        require(_dummy == _dummy);

        bool firstReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }
        firstCallFlag = firstReverted ? 1 : 0;

        bool secondReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }
        secondCallFlag = secondReverted ? 1 : 0;

        assert(secondCallFlag == 0);
    }

    receive() external payable {}
}

