// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;
    uint public firstCallFlag;
    uint public secondCallFlag;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _dummy) internal {
        vm.assume(_dummy == _dummy);
        bool firstReverted;
        try c.Initialized() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        firstCallFlag = firstReverted ? 1 : 0;
        bool secondReverted;
        try c.Initialized() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        secondCallFlag = secondReverted ? 1 : 0;
        assertTrue(secondCallFlag == 0);
    }

    function testFuzz_run(uint256 _dummy) public {
        _run(_dummy);
    }

    receive() external payable {}
}
